SELECT
FROM c LEFT JOIN sys_user u ON u.id = c.create_user LEFT JOIN sys_user_extend ue ON ue.id = c.create_user LEFT JOIN sys_user ru ON ru.id = c.reply_to_user_id WHERE c.organization_id = #{organizationId} AND c.resource_id = #{targetId}
AND c.parent_id IS NULL
AND c.parent_id = #{parentId}
ORDER BY c.create_time DESC, c.id DESC

